package local.castle.tv;
import android.content.*;import android.app.*;import android.media.*;import android.media.session.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import org.json.*;import java.util.*;
/** Device-local media progress, strictly restricted to YouTube and SmartTube. */
final class LivePlayback {
 static final String ACTION="local.castle.tv.PLAYBACK_CHANGED";
 static boolean allowedPackage(String p){return "com.google.android.youtube.tv".equals(p)||"org.smarttube.stable".equals(p)||"org.smarttube.beta".equals(p);}
 static boolean supported(Context c){return !(android.os.Build.VERSION.SDK_INT<=29&&((ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).isLowRamDevice());}
 static boolean enabled(Context c){if(!supported(c))return false;ComponentName n=new ComponentName(c,PlaybackListener.class);String s=Settings.Secure.getString(c.getContentResolver(),"enabled_notification_listeners");return s!=null&&Arrays.asList(s.split(":")).contains(n.flattenToString());}
 static String videoId(String s){if(s==null)return "";if(s.matches("[A-Za-z0-9_-]{11}"))return s;try{Uri u=Uri.parse(s);String v=u.getQueryParameter("v");if(v!=null&&v.matches("[A-Za-z0-9_-]{11}"))return v;String last=u.getLastPathSegment();if(last!=null&&last.matches("[A-Za-z0-9_-]{11}"))return last;}catch(Exception ignored){}return "";}
 static synchronized JSONArray rows(Context c){try{return new JSONArray(c.getSharedPreferences("castle-live",0).getString("rows","[]"));}catch(Exception e){return new JSONArray();}}
 static synchronized void save(Context c,MediaController controller){String pkg=controller.getPackageName();if(!allowedPackage(pkg))return;MediaMetadata m=controller.getMetadata();PlaybackState s=controller.getPlaybackState();if(m==null||s==null)return;String title=m.getString(MediaMetadata.METADATA_KEY_TITLE);if(title==null||title.trim().isEmpty())return;long pos=s.getPosition(),duration=m.getLong(MediaMetadata.METADATA_KEY_DURATION);if(s.getState()==PlaybackState.STATE_PLAYING&&s.getLastPositionUpdateTime()>0)pos+=Math.max(0,SystemClock.elapsedRealtime()-s.getLastPositionUpdateTime())*s.getPlaybackSpeed();pos=Math.max(0,duration>0?Math.min(duration,pos):pos);if(pos<1000)return;String id=videoId(m.getString(MediaMetadata.METADATA_KEY_MEDIA_ID));if(id.isEmpty())id=videoId(m.getString(MediaMetadata.METADATA_KEY_MEDIA_URI));String key=pkg+":"+(id.isEmpty()?title:id);JSONArray old=rows(c),out=new JSONArray();try{for(int i=0;i<old.length();i++){JSONObject prev=old.getJSONObject(i);if(key.equals(prev.optString("key"))&&pos==prev.optLong("position")&&duration==prev.optLong("duration")&&title.equals(prev.optString("title")))return;}JSONObject e=new JSONObject();e.put("key",key).put("pkg",pkg).put("id",id).put("title",title).put("position",pos).put("duration",duration).put("at",System.currentTimeMillis());String art=m.getString(MediaMetadata.METADATA_KEY_ART_URI);if(art==null)art=m.getString(MediaMetadata.METADATA_KEY_ALBUM_ART_URI);e.put("art",art==null?"":art);out.put(e);for(int i=0;i<old.length()&&out.length()<30;i++){JSONObject row=old.getJSONObject(i);if(!key.equals(row.optString("key")))out.put(row);}c.getSharedPreferences("castle-live",0).edit().putString("rows",out.toString()).apply();android.util.Log.i("CastlePlayback","Saved "+pkg+" position="+pos+" duration="+duration);c.sendBroadcast(new Intent(ACTION).setPackage(c.getPackageName()));}catch(Exception ignored){} }
 static List<TvShelf.Item> merge(Context c,List<TvShelf.Item> provider){if(!enabled(c))return provider;ArrayList<TvShelf.Item> out=new ArrayList<>();HashSet<String> observed=new HashSet<>();JSONArray data=rows(c);for(int i=0;i<data.length();i++)try{JSONObject e=data.getJSONObject(i);String pkg=e.optString("pkg"),id=e.optString("id");if(!allowedPackage(pkg))continue;if(!id.isEmpty())observed.add(id);long pos=e.optLong("position"),duration=e.optLong("duration");if(pos<1000||duration>0&&pos>=duration-3000)continue;TvShelf.Item x=new TvShelf.Item();x.pkg=pkg;x.title=e.optString("title");x.position=pos;x.duration=duration;x.engaged=e.optLong("at");x.poster=e.optString("art");x.source=(pkg.contains("smarttube")?"SmartTube":"YouTube")+" · "+I18n.tr("На этой приставке");x.type=0;x.id=-i-1;if(!id.isEmpty())x.intent=new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.youtube.com/watch?v="+id+"&t="+pos/1000)).setPackage(pkg).toUri(Intent.URI_INTENT_SCHEME);else{Intent launch=c.getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(launch==null)continue;x.intent=launch.toUri(Intent.URI_INTENT_SCHEME);}out.add(x);}catch(Exception ignored){}for(TvShelf.Item x:provider){boolean duplicate=false;for(String id:observed)if(x.intent.contains(id)){duplicate=true;break;}if(!duplicate&&out.size()<60)out.add(x);}Collections.sort(out,new Comparator<TvShelf.Item>(){public int compare(TvShelf.Item a,TvShelf.Item b){return Long.compare(b.engaged,a.engaged);}});return Collections.unmodifiableList(out);}
}
